from harvests import ROWS
from intake import parse_harvests

LINES = ["%s,%s" % (k, v) for k, v in ROWS]


def test_all_lines():
    records = parse_harvests("\n".join(LINES))
    assert [(x.field, x.kilos) for x in records] == [(k, v) for k, v in ROWS]


def test_trailing_newline():
    assert len(parse_harvests("\n".join(LINES) + "\n")) == len(ROWS)


def test_blank_lines():
    assert len(parse_harvests(LINES[0] + "\n\n" + LINES[1] + "\n  ")) == 2


def test_single_line():
    assert len(parse_harvests(LINES[0])) == 1


def test_empty_text():
    assert parse_harvests("") == []

